"""
Print report interactions in the PrintEngineV10 application
"""
from interops.libraries.squish_actions import CommonActions
import interops.libraries.desktop.aut_manager as AutManager
from interops.libraries.monaco.interactions.objects.monaco_core_objects import MonacoCoreObjects
from interops.libraries.monaco.interactions.objects.printenginev10_objects import PrintEngineV10Objects
from interops.libraries.squish_actions.constants import MONACO_APP_NAME, PRINT_ENGINE_APP_NAME
from interops.libraries.desktop import decorators as deco
from interops.libraries.common.state import State
from interops.libraries.miscellaneous.general_utility import create_path_if_does_not_exist

@deco.set_separate_app_context(MONACO_APP_NAME)
def launch_report(reportComment:str, reportType:str) -> list:
    """
    Launch the print Engine.

    :params: reportComment (str): User input comment to the report
             reportType (str): report type selected to show
    """
    report = MonacoCoreObjects.output_Toolbar_Report_Button
    report["id"] = reportType
    CommonActions.left_click_object(report)
    current_ctx = AutManager.get_current_app_context()
    CommonActions.type_in_textfield(CommonActions.wait_for_object_exists(MonacoCoreObjects.report_Comment_Edit), reportComment)
    CommonActions.left_click_object(MonacoCoreObjects.report_Comment_OK_Button)
    new_ctx = AutManager.wait_for_application_launch()
    return [current_ctx, new_ctx]

@deco.set_separate_app_context(PRINT_ENGINE_APP_NAME)
def create_report_path_if_needed(dirPath:str) -> bool:
    """
    Create the given dir path if it does not exist.

    :param: dirPath (str), the directory path.
    :return: bool to indicate if path is created.
    """
    try:
        if len(dirPath) <= 1:
            return False
        create_path_if_does_not_exist(dirPath)
        print(f"Path created: {dirPath}")
    except Exception as e:
        print(f"Error:{str(e)}")
        return False
    return True

@deco.set_separate_app_context(PRINT_ENGINE_APP_NAME)
def export_report_as(filePath:str):
    """
    Export the report as a PDF file by the given file path.

    :param: filePath (str), the full file path of the exported file.
    """
    try:
        CommonActions.left_click_object(PrintEngineV10Objects.export_Report_Button)
        CommonActions.os_choose_file(filePath)
        print(f"File saved: {filePath}")
    except Exception as e:
        print(f"Error:{str(e)}")

@deco.set_separate_app_context(PRINT_ENGINE_APP_NAME)
def export_report_to(dirPath:str):
    """
    Export the report to a directory with a default file name.

    :param: dirPath (str), the path where the exported file locates
    """
    try:
        CommonActions.left_click_object(PrintEngineV10Objects.export_Report_Button)
        CommonActions.wait_for_object_exists(PrintEngineV10Objects.output_File_Name_ComboBox)
        output_file = State(PrintEngineV10Objects.output_File_Name_ComboBox)
        filePath = dirPath  + str(output_file.value)
        output_file.value = filePath

        CommonActions.left_click_object(PrintEngineV10Objects.save_Button)
        if CommonActions.find_any_object([PrintEngineV10Objects.confirm_Save_As_Dialog], 3000):
            CommonActions.left_click_object(PrintEngineV10Objects.yes_Button)
        print(f"File saved: {filePath}")
    except Exception as e:
        print(f"Error:{str(e)}")

@deco.set_separate_app_context(PRINT_ENGINE_APP_NAME)
def close_print_engine(reportType:str):
    """
    Close the print engine

    :param: reportType (str) the report type associated with the print engine.
    """
    report_dlg = PrintEngineV10Objects.printEngine_Report_Dialog
    report_dlg["text"] = reportType
    report_dlg_obj =  CommonActions.find_any_object([report_dlg])
    if report_dlg_obj:
        CommonActions.mouse_click_with_relative_x_and_y_offsets(report_dlg_obj, report_dlg_obj.width-16, 16)